import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import API from '../api/axios';
import { ShieldAlert, Loader2 } from 'lucide-react';

export default function Login() {
  const navigate = useNavigate();
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  // Backend verification handler
  const verifyAndLogin = async (email, name) => {
    try {
      setLoading(true);
      setError('');
      const res = await API.post('/auth/google-login', {
        email: email.trim().toLowerCase(),
        name: name || email.split('@')[0]
      });

      if (res.data.success && res.data.token) {
        localStorage.setItem('admin_token', res.data.token);
        localStorage.setItem('admin_user', JSON.stringify(res.data.user));
        navigate('/dashboard');
      }
    } catch (err) {
      setError(
        err.response?.data?.error || 'Ei Gmail account-ti admin hishebe onumodito noy!'
      );
    } finally {
      setLoading(false);
    }
  };

  // JWT Token theke email decode korar helper function
  const parseJwt = (token) => {
    try {
      const base64Url = token.split('.')[1];
      const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
      const jsonPayload = decodeURIComponent(
        atob(base64)
          .split('')
          .map((c) => '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2))
          .join('')
      );
      return JSON.parse(jsonPayload);
    } catch (e) {
      return null;
    }
  };

  // Google credential callback
  const handleCredentialResponse = (response) => {
    if (!response || !response.credential) {
      setError('Google theke account information paowa jai ni!');
      return;
    }

    const payload = parseJwt(response.credential);
    if (payload && payload.email) {
      verifyAndLogin(payload.email, payload.name);
    } else {
      setError('Gmail address identify kora jai ni!');
    }
  };

  useEffect(() => {
    // Jodi age thekei logged in thake
    if (localStorage.getItem('admin_token')) {
      navigate('/dashboard');
      return;
    }

    // Google GSI button initialization
    const loadGoogleBtn = () => {
      if (window.google && window.google.accounts && window.google.accounts.id) {
        window.google.accounts.id.initialize({
          client_id: '892348234723-dummyclientid.apps.googleusercontent.com',
          callback: handleCredentialResponse,
          auto_select: true
        });

        const btnContainer = document.getElementById('googleSignInBtnWrapper');
        if (btnContainer) {
          window.google.accounts.id.renderButton(btnContainer, {
            theme: 'outline',
            size: 'large',
            shape: 'pill',
            width: 320,
            text: 'continue_with'
          });
        }
      }
    };

    const timer = setTimeout(loadGoogleBtn, 300);
    return () => clearTimeout(timer);
  }, [navigate]);

  return (
    <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4 font-sans">
      <div className="bg-white rounded-3xl p-8 max-w-sm w-full shadow-2xl space-y-6 text-center">
        <div>
          <div className="w-16 h-16 bg-emerald-100 text-emerald-800 rounded-2xl flex items-center justify-center mx-auto mb-3 font-black text-2xl shadow-inner">
            CF
          </div>
          <h2 className="text-2xl font-black text-gray-900">CityFood Control</h2>
          <p className="text-xs text-gray-500 font-semibold mt-1">Authorized Gmail Sign-In</p>
        </div>

        {error && (
          <div className="p-3 bg-red-50 border border-red-200 text-red-700 text-xs rounded-xl flex items-center gap-2 font-bold text-left leading-relaxed">
            <ShieldAlert className="w-4 h-4 flex-shrink-0 text-red-600" />
            <span>{error}</span>
          </div>
        )}

        {loading ? (
          <div className="py-6 flex flex-col items-center justify-center gap-2 text-xs font-bold text-emerald-700">
            <Loader2 className="w-6 h-6 animate-spin text-emerald-600" />
            <span>Gmail onumodon jachai kora hocche...</span>
          </div>
        ) : (
          <div className="flex flex-col items-center justify-center pt-2">
            {/* Shudhu Google Sign-In Button */}
            <div id="googleSignInBtnWrapper" className="flex justify-center w-full min-h-[44px]"></div>
          </div>
        )}

        <div className="bg-gray-50 p-3.5 rounded-2xl border border-gray-100 text-[10px] text-gray-500 font-medium leading-relaxed">
          🔒 Shudhumatro <strong>tanvir.it009@gmail.com</strong> ebong system-e onumodito sub-admin accounts-i ekhane login korte parbe।
        </div>
      </div>
    </div>
  );
}
